   const count=BigInt(Math.max(1,Math.floor(batch)))<remaining?BigInt(Math.max(1,Math.floor(batch))):remaining,before=rt.time,t=performance.now();
   const result=driverCall('advance',count,options),advanced=rt.time-before,elapsed=Math.max(.1,performance.now()-t);remaining-=advanced;batch=advanced>0n?Math.max(1,Math.min(Number(count)*2,Math.floor(Number(advanced)*12/elapsed))):1;
