 function updateToolbar(){if(!S.project)return;const parentButton=$('[data-action=parent]');if(parentButton)parentButton.hidden=!S.parents.length;$('#run-button').textContent=S.advancing?'Ⅱ 取消推进':S.running?'Ⅱ 暂停':'▶ 运行';$('#run-button').classList.toggle('running',S.running||S.advancing);$('#running-light').classList.toggle('on',S.running);$('#draft-banner').hidden=!S.dirty;$('#project-status').textContent=S.dirty?'待应用':S.running?'运行中':S.pendingTime?'输入待执行':S.sourcePending?'源码待编译':'已暂停';$('#project-status').classList.toggle('dirty',S.dirty);const domains=S.state?.domains||{},on=Object.values(domains).some(d=>d.isPowered);$('#power-button').textContent=on?'⏻ 已上电':'⏻ 已断电';const t=BigInt(S.state?.time||'0');$('#virtual-time').textContent=t<1000n?t+' μs':t<1000000n?(Number(t)/1000).toFixed(2)+' ms':(Number(t/1000n)/1000).toFixed(3)+' s';}
