 async function importWorkspaceFile(file){if(!file)return;if(file.size>8*1024*1024)throw new Error('文件超过 8 MB。');const text=await file.text(),raw=CL.parseJSON(text);if(raw.format==='silicon-lab.session/1'){await restoreSession(raw);}else if(raw.format==='silicon-lab.workspace/1'){const allowed=['format','project','view','sources','lesson'];if(Object.keys(raw).some(k=>!allowed.includes(k)))throw new Error('工作台文件含未知字段。');if(raw.sources&&Object.entries(raw.sources).some(([k,v])=>typeof v!=='string'||v.length>100000))throw new Error('源码格式错误。');await loadWorkspace(raw);}else if(raw.format==='silicon-lab.snapshot/1'){await loadWorkspace(raw.workspace,{snapshot:raw.snapshot});}else await loadWorkspace({project:await CL.importProject(text)});notify('工程已载入。内容校验通过。');}
