 async function verify(){if(!S.lesson)return;const button=$('#verify-button');button.disabled=true;stop();try{const result=S.lesson.startsWith('board:')?await ChipLibrary.verifyBoard(S.lesson.slice(6),copy(S.project)):S.lesson.startsWith('v2:')?await V2Examples.verify(S.lesson.slice(3),copy(S.project)):await LL.verify(S.lesson,copy(S.project));if(result.ok&&LL.list.some(x=>x.id===S.lesson))rememberProgress(S.lesson);modal(result.ok?'实验完成，新的可能已开启':'再调整一下，离答案更近了',`<p class="dialog-lead">验证在独立电路副本中运行，保留你当前的程序位置和运行状态。判断实际输入输出，不限定元件摆放方式。</p><div class="check-list">${(result.checks||[{label:result.ok?'行为符合目标':'未通过',ok:result.ok,detail:result.error||''}]).map(c=>`<div class="check-row ${c.ok?'':'fail'}"><span class="check-icon">${c.ok?'✓':'○'}</span><div>${escape(c.label)}<small>${escape(c.detail||'')}</small></div></div>`).join('')}</div>`,`<button class="quiet-btn" data-action="hint">查看提示</button><button class="outline-btn" data-action="lessons">继续探索 →</button>`);}catch(e){notify(errorMessage(e),true);}finally{button.disabled=false;}}
 function hint(){const l=currentExperiment();if(!l)return help();const hints=l.hints||[l.goal];const h=hints[Math.min(S.hints,hints.length-1)];S.hints++;modal(l.title+' · 提示',`<p class="dialog-lead">第 ${Math.min(S.hints,hints.length)} / ${hints.length} 层提示</p><div class="hint-box">${escape(typeof h==='string'?h:h.text||JSON.stringify(h))}</div>`,`<button class="quiet-btn" data-action="close-dialog">回到电路</button>${S.hints<hints.length?'<button class="outline-btn" data-action="hint">再给一点提示 →</button>':''}`);}
 function help(){modal('你的数字创造实验室',`<p class="dialog-lead">这里的灯、逻辑和串口由真正的电路模型决定。先运行一个示例，再改一根线或一条指令，观察它如何变化。</p><div class="help-grid"><article><h3>01 / 连接电路</h3><p>点击左侧元件加入工作台。依次点击两个端口建立连线；拖动标题移动元件。Shift 点击多选，空白处拖动框选。Ctrl / ⌘ C、V 复制粘贴；Delete 删除，Ctrl / ⌘ Z 撤销，Esc 取消接线。</p></article><article><h3>02 / 上电与运行</h3><p>修改拓扑后点击「应用并重新启动」。运行让虚拟时间前进；暂停冻结整个电路。单步执行一条 MCU 指令，普通电路则推进一微秒。</p></article><article><h3>03 / 看清信号</h3><p>绿色表示高电平；0 是低电平。X 表示未知或冲突，Z 表示未驱动。点击导线可暂时断开，发送器不会因此凭空停止。</p></article><article><h3>04 / 创造自己的芯片</h3><p>放置输入与输出，接好电路，再「封装芯片」；MCU 模块会携带固件和供电配置。同一芯片可以使用多次，各有独立状态。打开其内部设计后，修改并保存新版本。</p></article><article><h3>05 / 保存与快照</h3><p>「我的作品」提供手动保存、自动备份和有限历史。历史同时保留未应用草稿、源码和真实运行现场；导出现场可跨设备备份。</p></article><article><h3>06 / 扩展实验室</h3><p>提供逻辑门、记忆单元、Core8、GPIO 和事务串口。新版 Core8/2 提供定时器、中断、PWM、SPI 和 I²C。芯片包可导出分享；在线共享与联机方案见交付文档。</p></article></div>`,`<button class="outline-btn" data-action="lessons">选择一个实验 →</button>`);}
 function basicInstructions(){const rows=[['LDI R0, 42','装入一个 0—255 的数'],['MOV R0, R1','复制寄存器'],['ADD / SUB R0, R1','八位加减，超出按 256 回绕'],['AND / OR / XOR R0, R1','按位逻辑'],['NOT R0','八位取反'],['SHL / SHR R0, 1','移位 0—7 位'],['LD R0, 0x4002','从地址读取一字节'],['ST R0, 0x4001','向地址写入一字节'],['JMP loop','无条件跳转'],['JZ / JNZ R0, loop','为零 / 非零时跳转'],['WAIT 60000','等待指定微秒数'],['NOP / HALT','空操作 / 停止 CPU']];modal('Core8 指令速查',`<p class="dialog-lead">寄存器 R0—R7；每条指令固定 4 字节。数字支持十进制与 0x 十六进制。以分号添加注释。WAIT 使用微秒，不是毫秒。</p><table class="instruction-table"><thead><tr><th>示例</th><th>作用</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escape(r[0])}</td><td>${escape(r[1])}</td></tr>`).join('')}</tbody></table><p class="scope-note">GPIO：DIR 0x4000，OUT 0x4001，IN 0x4002，弱下拉 0x4003。UART：TXDATA 0x4100，RXDATA 0x4101，STATUS 0x4102，CTRL 0x4103。开启收发：向 CTRL 写 3。</p>`);}
