  async function probe(d){const p=await CL.createProject('版本比较');mergeDefinitions(p,dependencies);mergeDefinitions(p,[d]);for(const port of inputs)CL.addInput(p,port.id,port.name,0,port.width);for(const port of outputs)CL.addOutput(p,port.id,port.name,port.width);p.circuit.instances.push({id:'probe',label:d.name,definition:identity(d),parameters:{},bindings:{power:'main'}});for(const port of inputs)CL.addWire(p,'in_'+port.id,CL.boundary(port.id),CL.ep('probe',port.id));for(const port of outputs)CL.addWire(p,'out_'+port.id,CL.ep('probe',port.id),CL.boundary(port.id));return new CL.Runtime(await CL.importProject(p));}
