  for(let vector=0;vector<2**bits;vector++){let offset=0;const values=[];for(const p of inputs){const v=Math.floor(vector/2**offset)%2**p.width;offset+=p.width;values.push(p.id+'='+v);old.setInput(p.id,v);next.setInput(p.id,v);}old.advance(1n,{force:true});next.advance(1n,{force:true});const before=outputs.map(p=>p.id+'='+textSignal(old.getPort(CL.boundary(p.id)))).join(', '),after=outputs.map(p=>p.id+'='+textSignal(next.getPort(CL.boundary(p.id)))).join(', ');if(before!==after)changes++;if(rows.length<8&&before!==after)rows.push('<tr><td>'+escape(values.join(', ')||'无输入')+'</td><td>'+escape(before)+'</td><td>'+escape(after)+'</td></tr>');}
