  let nextSources=copy(S.sources),nextView=copy(S.view);try{if(item.module){const wires=next.circuit.wires;next.circuit.wires=wires.filter(w=>!(w.from.kind==='instance'&&w.from.instance===n.id)&&!(w.to.kind==='instance'&&w.to.instance===n.id));next.circuit.instances=next.circuit.instances.filter(x=>x.id!==n.id);const placed=await CL.placeModule(next,item.module,n.id,n.label,{exposePorts:false});next.circuit.wires=wires;Object.assign(nextSources,placed.sourceMap);nextView.moduleOrigins||={};nextView.moduleOrigins[n.id]={...identity(item.definition),placedHash:placed.definition.contentHash};}else{mergeDefinitions(next,[...item.dependencies,after]);const target=next.circuit.instances.find(x=>x.id===n.id);target.definition=identity(after);if(after.contract.timing==='stateful'){target.bindings.clock='global.1us';target.bindings.reset='global.warm';}else{delete target.bindings.clock;delete target.bindings.reset;}}await CL.importProject(next);}catch(e){compatible=false;validation=errorMessage(e);}
